def enrich(raw):
 for model,(finding,scale) in findings.items():
  # Insert after each project question, before the expandable method notes.
  pattern=r'(<article[^>]*>.*?href="https://lab\.yourcatalyst\.in/experiments/#'+model+r'".*?)(<details\s)'
  friction,check,line=checks[model]
  validation=grounding(['<strong>Real friction:</strong> '+friction,'<strong>Validation:</strong> '+check])+chip('Model source',repo+f'/blob/main/experiments/models.mjs#L{line}')
  extra=takeaway('SEEDED MODEL EXAMPLE / SEED 42',finding)+validation+f'<p class="research-scope"><strong>Limitations</strong> · {limits[model]}</p>'+f'<p class="stack-line"><strong>Stack</strong> JavaScript ES modules · SVG · node:test · GitHub Pages</p><p class="scale-line"><strong>Computation</strong> {scale}</p><p class="evidence-link"><a href="evidence/experiment-results.json">Exact parameters &amp; outputs ↗</a></p>'
  raw=re.sub(pattern,lambda m:m.group(1)+extra+m.group(2),raw,count=1,flags=re.S)
 return raw

