# Record exactly what can be reproduced from the existing public DAO summaries.
source=r/'evidence/dao-source-summary.py'
import ast,math
module=ast.parse(source.read_text());pairs=next(ast.literal_eval(node.value) for node in module.body if isinstance(node,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='DATA' for t in node.targets))
for row in pairs:
 row['computed_strict_k_min']=math.floor((1+row['G']/row['W'])**2)+1
 row['gain_at_threshold']=(math.sqrt(row['computed_strict_k_min'])-1)*row['W']
 row['gain_one_below']=(math.sqrt(row['computed_strict_k_min']-1)-1)*row['W']
evidence={'scope':'Reconstruction from four hard-coded published W/G summary pairs. This verifies algebraic consistency, not raw-ballot provenance or a real attack.','source_url':'https://github.com/thetarocks/dao-sybil-resilience/blob/main/run_sybil_pipeline.py','source_sha256':hashlib.sha256(source.read_bytes()).hexdigest(),'condition':'(sqrt(k)-1)*W > G','cases':pairs}
(site/'evidence/sybil-boundaries.json').write_text(json.dumps(evidence,indent=2)+'\n')
